// Draws the procedural layers for Mio, this example's character (plan §6.2
// folder convention). Simple shapes only: placeholders are procedural, never
// generated by AI (plan §1.5). Run from this folder: node make-art.mjs
import { mkdirSync, writeFileSync } from "node:fs";
import { deflateSync } from "node:zlib";

const W = 400;
const H = 900;

function crc32(buf) {
  let c = ~0;
  for (const b of buf) {
    c ^= b;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  }
  return ~c >>> 0;
}

function png(rgba) {
  const raw = Buffer.alloc((W * 4 + 1) * H);
  for (let y = 0; y < H; y++) rgba.copy(raw, y * (W * 4 + 1) + 1, y * W * 4, (y + 1) * W * 4);
  const chunk = (type, data) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(td));
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

/** A layer: a transparent canvas plus shape helpers. */
function layer(draw) {
  const px = Buffer.alloc(W * H * 4);
  const put = (x, y, [r, g, b, a = 255]) => {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    const i = (y * W + x) * 4;
    px[i] = r;
    px[i + 1] = g;
    px[i + 2] = b;
    px[i + 3] = a;
  };
  const ellipse = (cx, cy, rx, ry, color) => {
    for (let y = Math.floor(cy - ry); y <= cy + ry; y++)
      for (let x = Math.floor(cx - rx); x <= cx + rx; x++)
        if (((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1) put(x, y, color);
  };
  const rect = (x0, y0, x1, y1, color) => {
    for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) put(x, y, color);
  };
  draw({ ellipse, rect });
  return png(px);
}

const SKIN = [250, 222, 200];
const INK = [60, 40, 50];
const files = {
  "body/base": ({ ellipse, rect }) => {
    rect(170, 300, 230, 360, SKIN); // neck
    ellipse(200, 210, 110, 125, SKIN); // head
    ellipse(200, 120, 125, 85, [90, 60, 50]); // hair
    rect(110, 350, 290, 900, SKIN); // arms and body under the outfit
  },
  "outfit/uniform": ({ rect }) => {
    rect(100, 360, 300, 900, [40, 60, 120]);
    rect(185, 360, 215, 470, [200, 40, 60]); // tie
  },
  "outfit/casual": ({ rect }) => rect(100, 360, 300, 900, [240, 180, 80]),
  "eyes/neutral": ({ ellipse }) => {
    ellipse(160, 215, 14, 20, INK);
    ellipse(240, 215, 14, 20, INK);
  },
  "eyes/neutral_half": ({ rect }) => {
    rect(146, 213, 175, 225, INK);
    rect(226, 213, 255, 225, INK);
  },
  "eyes/neutral_closed": ({ rect }) => {
    rect(144, 220, 177, 225, INK);
    rect(224, 220, 257, 225, INK);
  },
  "eyes/smile": ({ ellipse, rect }) => {
    ellipse(160, 222, 16, 10, INK);
    ellipse(240, 222, 16, 10, INK);
    rect(140, 222, 180, 236, SKIN);
    rect(220, 222, 260, 236, SKIN);
  },
  "mouth/neutral": ({ rect }) => rect(185, 272, 215, 277, INK),
  "mouth/neutral_open": ({ ellipse }) => ellipse(200, 276, 14, 10, [150, 50, 60]),
  "mouth/smile": ({ ellipse, rect }) => {
    ellipse(200, 268, 22, 14, INK);
    rect(170, 250, 230, 268, SKIN);
  },
  "mouth/smile_open": ({ ellipse }) => ellipse(200, 274, 22, 14, [150, 50, 60]),
  "accessories/ribbon": ({ ellipse }) => {
    ellipse(285, 95, 34, 22, [230, 70, 120]);
    ellipse(315, 95, 34, 22, [230, 70, 120]);
  },
};

for (const [name, draw] of Object.entries(files)) {
  const dir = `assets/sprites/mio/${name.split("/")[0]}`;
  mkdirSync(dir, { recursive: true });
  writeFileSync(`assets/sprites/mio/${name}.png`, layer(draw));
}
console.log(`wrote ${Object.keys(files).length} layers to assets/sprites/mio/`);
